#include <iostream>
#include <string>
using namespace std;

class Cat {
public:
    string name;
    Cat(string n) : name(n) {
        cout << name << " 出生啦" << endl;
    }
    ~Cat() {
        cout << name << " 走啦" << endl;
    }
};

void kitchen() {
    Cat tmp("胖虎");
    cout << tmp.name << " 吃饱了" << endl;
}

int main() {
    Cat a("小橘");
    kitchen();
    Cat b("狸花");
    cout << "开饭结束" << endl;
    return 0;
}

